      render: (_, r) => (r as any).siteName || r.siteCode,
      valueType: 'select',
      fieldProps: {
        options: siteOptions,
        allowClear: true,
        placeholder: '全部站点',
      },
    },
    {
      title: '日期',
      dataIndex: 'liveDate',
      width: 110,
      valueType: 'date',
    },
    { title: '直播间ID', dataIndex: 'roomId', width: 110, search: false },
    {
      title: '赛事时间',
      dataIndex: 'eventTime',
      width: 80,
      search: false,
      render: (_, row) => (row as any).eventTime || '-',
    },
    {
      title: '联赛',
      dataIndex: 'league',
      width: 80,
      fieldProps: { placeholder: '模糊搜索联赛' },
      render: (_, row) => (row as any).league || '-',
    },
    {
      title: '赛事',
      dataIndex: 'eventName',
      width: 160,
      ellipsis: true,
      fieldProps: { placeholder: '模糊搜索赛事' },
      render: (_, row) => (row as any).eventName || (row as any).liveInfo || '-',
    },
    {
      title: '类型',
      dataIndex: 'category',
      width: 100,
      fieldProps: { placeholder: '模糊搜索类型' },
    },
    {
      title: '主播',
      dataIndex: 'host',
      width: 100,
      fieldProps: { allowClear: true, placeholder: '全部' },
    },
    {
      title: '开播时间',
      dataIndex: 'startTime',
      width: 170,
      valueType: 'dateTime',
      search: false,
    },
    {
      title: '直播时长',
      dataIndex: 'duration',
      width: 110,
      search: false,
      render: (_, row) => formatDuration(row.duration),
    },
    {
      title: '评论数',
      dataIndex: 'commentCount',
      width: 90,
      sorter: true,
      search: false,
      render: (_, row) => (row.commentCount ?? 0).toLocaleString(),
    },
    {
      title: '次均停留',
      dataIndex: 'avgStayVisit',
      width: 100,
      sorter: true,
      search: false,
      render: (_, row) => formatDuration(row.avgStayVisit),
    },
    {
      title: '人均停留',
      dataIndex: 'avgStayPerson',
      width: 100,
      sorter: true,
      search: false,
      render: (_, row) => formatDuration(row.avgStayPerson),
    },
    {
      title: '峰值在线',
      dataIndex: 'peakOnline',
      width: 90,
      sorter: true,
      search: false,
      render: (_, row) => (row.peakOnline ?? 0).toLocaleString(),
    },
    {
      title: '操作',
      valueType: 'option',
      width: 80,
      render: (_, row) => [
        <Popconfirm
          key="delete"
          title="确认删除？"
          onConfirm={async () => {
            await deleteLiveStreamRecord(row.id);
            msg.success('已删除');
            actionRef.current?.reload();
          }}
        >
          <a>删除</a>
        </Popconfirm>,
      ],
    },
  ];

  const summaryColumns: ProColumns<API.DailySummaryRecord>[] = [
    {
      title: '站点',
      dataIndex: 'siteCode',
      width: 150,
      ellipsis: true,
      render: (_, r) => r.siteName || r.siteCode,
      valueType: 'select',
      fieldProps: {
        options: siteOptions,
        allowClear: true,
        placeholder: '全部站点',
      },
    },
    {
      title: '日期',
      dataIndex: 'liveDate',
      width: 120,
      valueType: 'date',
    },
    {
      title: '主播数',
      dataIndex: 'hostCount',
      width: 80,
      search: false,
    },
    {
      title: '评论总数',
      dataIndex: 'totalComments',
      width: 100,
